-- Golden-fixture parity tests: denote.nvim must produce byte-for-byte the same file names,
-- front matter, links, slugs and parsed components as the real Emacs Denote.
--
-- The fixtures are generated by `make fixtures` (scripts/emacs-fixtures/generate.el), which
-- drives the actual Denote package from GNU ELPA under Emacs.  Never edit them by hand.

local denote = require("denote")
local frontmatter = require("denote.frontmatter")
local links = require("denote.links")
local naming = require("denote.naming")

local root = vim.fn.fnamemodify(debug.getinfo(1, "S").source:sub(2), ":p:h:h:h")
local fixture_path = root .. "/tests/fixtures/emacs/denote.json"
--- Turn JSON nulls (`vim.NIL`) into Lua nils.
local function denil(v)
  if v == vim.NIL then
    return nil
  elseif type(v) == "table" then
    for k, item in pairs(v) do
      v[k] = denil(item)
    end
  end
  return v
end
local fixtures = denil(vim.json.decode(table.concat(vim.fn.readfile(fixture_path), "\n")))

--- Cases where denote.nvim deliberately (or for now) differs from Emacs Denote.
--- `id` is a prefix of the check ids used below ("<category>/<case>/<aspect>"); `aspects`, when
--- given, limits the entry to check ids ending in one of those aspects.
--- A known difference is still checked: the test fails if denote.nvim starts to AGREE with
--- Emacs, so that the entry gets removed instead of rotting here.
local BACKSLASH_ANGLE = "denote.nvim's default `excluded_punctuation_pattern` (and its signature sluggifier) "
  .. "also strip `\\ < >`, which are unsafe in file names on some systems; Emacs keeps them"
local KNOWN_DIFFERENCES = {
  {
    id = "notes/keywords-mixed-case-sort/",
    aspects = { "filename", "front_matter", "create_sync" },
    reason = "Emacs sorts the raw keywords (`string-collate-lessp`, locale dependent) before sluggifying "
      .. "them; denote.nvim sorts the sluggified keywords bytewise",
  },
  {
    id = "notes/keywords-duplicates/",
    aspects = { "filename", "front_matter", "create_sync" },
    reason = "Emacs' `denote` Lisp API keeps duplicate keywords (only its interactive prompt de-duplicates); "
      .. "denote.nvim always de-duplicates",
  },
  { id = "notes/title-angle-brackets/", aspects = { "filename", "create_sync" }, reason = BACKSLASH_ANGLE },
  { id = "notes/title-quotes-backslash/", aspects = { "filename", "create_sync" }, reason = BACKSLASH_ANGLE },
  { id = "slugs/back\\slash/", reason = BACKSLASH_ANGLE },
  { id = "slugs/a<b>c/", reason = BACKSLASH_ANGLE },
  {
    id = "slugs/tab\tseparated/",
    reason = "Emacs only treats spaces as word separators (tabs are kept verbatim); denote.nvim treats any "
      .. "whitespace as a separator",
  },
  {
    id = "parse/@@custom-id--free-form-identifier.md/identifier",
    reason = "denote.nvim only recognises date identifiers (YYYYMMDDTHHMMSS); Emacs Denote 4.x also accepts "
      .. "free-form `@@` identifiers",
  },
}

local function known_difference(id)
  for _, kd in ipairs(KNOWN_DIFFERENCES) do
    if id:sub(1, #kd.id) == kd.id then
      if not kd.aspects then
        return kd.reason
      end
      for _, aspect in ipairs(kd.aspects) do
        if id:sub(-#aspect - 1) == "/" .. aspect then
          return kd.reason
        end
      end
    end
  end
end

--- Register one parity check. `compute` returns denote.nvim's value; `expected` is Emacs'.
local function check(id, expected, compute)
  local reason = known_difference(id)
  if reason then
    it(id .. " [known difference: " .. reason .. "]", function()
      local actual = compute()
      ok(
        not vim.deep_equal(expected, actual),
        "denote.nvim now matches Emacs for " .. id .. ": remove it from KNOWN_DIFFERENCES"
      )
    end)
  else
    it(id, function()
      eq(expected, compute(), id)
    end)
  end
end

local function setup(extra)
  denote.setup(vim.tbl_extend("force", {
    mappings = { enabled = false },
    known_keywords = {},
  }, extra or {}))
end

local SYNTAX = { org = "org", ["markdown-yaml"] = "markdown", ["markdown-toml"] = "markdown", text = "text" }
local FILE_TYPES = { "org", "markdown-yaml", "markdown-toml", "text" }

local function read_file(path)
  local fd = assert(io.open(path, "rb"))
  local data = fd:read("*a")
  fd:close()
  return data
end

local function write_file(path, data)
  local fd = assert(io.open(path, "wb"))
  fd:write(data)
  fd:close()
end

-- All dates in the fixtures are rendered in a fixed time zone.
-- Changing $TZ is not enough on glibc: LuaJIT's os.date uses localtime_r(), which does not
-- re-read $TZ (mktime() behind os.time does), so call tzset() explicitly after every change.
local ffi = require("ffi")
pcall(ffi.cdef, "void tzset(void);")
local function set_tz(tz)
  vim.env.TZ = tz
  pcall(function()
    ffi.C.tzset()
  end)
end
local saved_tz = vim.env.TZ
set_tz(fixtures.tz)

describe("Emacs Denote " .. fixtures.denote_version .. " golden fixtures", function()
  it("fixture file is populated", function()
    ok(#fixtures.notes > 0 and #fixtures.orders > 0 and #fixtures.slugs > 0, "empty fixture file")
    ok(#fixtures.links > 0 and #fixtures.parse > 0, "empty fixture file")
  end)

  describe("new notes (file name + front matter)", function()
    for _, case in ipairs(fixtures.notes) do
      local input = case.input
      for _, ft in ipairs(FILE_TYPES) do
        local out = case.outputs[ft]
        local prefix = "notes/" .. case.name .. "/" .. ft

        check(prefix .. "/filename", out.filename, function()
          setup({ file_type = ft })
          return naming.format_filename({
            identifier = naming.format_identifier(input.date),
            signature = input.signature,
            title = input.title,
            keywords = input.keywords or {},
            extension = frontmatter.extension_for(ft),
          })
        end)

        check(prefix .. "/front_matter", out.contents, function()
          setup({ file_type = ft })
          -- Mirrors create.lua: the signature is sluggified before reaching the front matter.
          return frontmatter.format({
            title = input.title,
            date = input.date,
            keywords = input.keywords or {},
            identifier = naming.format_identifier(input.date),
            signature = naming.sluggify_signature(input.signature or ""),
            file_type = ft,
          })
        end)

        check(prefix .. "/create_sync", { out.filename, out.contents }, function()
          local result
          with_temp_dir(function(dir)
            setup({ directory = dir, file_type = ft })
            local note = denote.create_sync({
              title = input.title,
              keywords = input.keywords or {},
              signature = input.signature,
              file_type = ft,
              date = input.date,
              open = false,
            })
            result = { vim.fs.basename(note.path), read_file(note.path) }
          end)
          return result
        end)
      end
    end
  end)

  describe("file_name_components_order", function()
    for _, case in ipairs(fixtures.orders) do
      local input = case.input
      local opts = {
        file_name_components_order = case.file_name_components_order,
        identifier_delimiter_always_present = case.identifier_delimiter_always_present,
      }
      local prefix = "orders/" .. case.name

      check(prefix .. "/filename", case.filename, function()
        setup(opts)
        return naming.format_filename({
          identifier = naming.format_identifier(input.date),
          signature = input.signature,
          title = input.title,
          keywords = input.keywords or {},
          extension = ".md",
        })
      end)

      check(prefix .. "/parse", case.parsed, function()
        setup(opts)
        local p = naming.parse_filename(case.filename)
        return {
          identifier = p.identifier,
          title = p.title,
          signature = p.signature,
          keywords = #p.keywords > 0 and table.concat(p.keywords, "_") or nil,
        }
      end)
    end
  end)

  describe("sluggification", function()
    for _, case in ipairs(fixtures.slugs) do
      local prefix = "slugs/" .. case.input
      check(prefix .. "/title", case.title, function()
        setup()
        return naming.sluggify_title(case.input)
      end)
      check(prefix .. "/signature", case.signature, function()
        setup()
        return naming.sluggify_signature(case.input)
      end)
      check(prefix .. "/keyword", case.keyword, function()
        setup()
        return naming.sluggify_keyword(case.input)
      end)
    end
  end)

  describe("links", function()
    for _, case in ipairs(fixtures.links) do
      local desc = case.input.description
      for _, ft in ipairs(FILE_TYPES) do
        local out = case.outputs[ft]
        local prefix = "links/" .. case.name .. "/" .. ft
        local id = naming.parse_filename(out.filename).identifier
        local syntax = SYNTAX[ft]

        check(prefix .. "/default_description", out.default_description, function()
          local result
          with_temp_dir(function(dir)
            setup({ directory = dir, file_type = ft })
            local path = dir .. "/" .. out.filename
            write_file(path, out.contents)
            result = links.default_description(path)
          end)
          return result
        end)

        check(prefix .. "/with_description", out.link_with_description, function()
          setup({ file_type = ft })
          return links.format_link(id, desc, { syntax = syntax })
        end)

        check(prefix .. "/default_description_link", out.link_default_description, function()
          setup({ file_type = ft })
          return links.format_link(id, out.default_description, { syntax = syntax })
        end)

        check(prefix .. "/empty_description", out.link_empty_description, function()
          setup({ file_type = ft })
          return links.format_link(id, "", { syntax = syntax })
        end)

        check(prefix .. "/id_only", out.link_id_only, function()
          setup({ file_type = ft })
          return links.format_link(id, desc, { syntax = syntax, id_only = true })
        end)
      end
    end
  end)

  describe("file name parsing", function()
    for _, case in ipairs(fixtures.parse) do
      local p
      local function parsed()
        setup()
        p = p or naming.parse_filename(case.filename)
        return p
      end
      local prefix = "parse/" .. case.filename
      check(prefix .. "/identifier", case.identifier, function()
        return parsed().identifier
      end)
      check(prefix .. "/title", case.title, function()
        return parsed().title
      end)
      check(prefix .. "/signature", case.signature, function()
        return parsed().signature
      end)
      check(prefix .. "/keywords", case.keywords, function()
        local kws = parsed().keywords
        return #kws > 0 and table.concat(kws, "_") or nil
      end)
    end
  end)
end)

set_tz(saved_tz)
denote.setup({ mappings = { enabled = false } })
